INSERT INTO public.stages (code, order_num, title, category, description) VALUES ('7', 7, 'Atelier Intelligence Artificielle', 'IA', 'Huit défis interactifs face à des assistants scriptés : contournement de filtre, protection des données personnelles, hameçonnage, vérification des réponses, secrets dans le code, garde-fous à détourner, exfiltration par filtre de sortie et épreuve finale multi-défenses.') ON CONFLICT (code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description;

-- Défi 7.8 : Cerbère
INSERT INTO public.challenges (id, stage_code, stage_order, challenge_order, title, category, difficulty, estimated_minutes, points, status, objective, scenario, environment, instructions, expected_submission, prerequisite_ids, tags, student_materials, submission_fields, version)
VALUES ('cerbere-final', '7', 7, 8, 'Cerbère', 'IA', 'N6', 90, 1000, 'published'::public.challenge_status, 'Contourner les défenses de Cerbère : jouer un rôle d''auditeur autorisé, déclencher une empreinte de contrôle, exfiltrer le sceau en deux fragments masqués, les décoder et soumettre le flag.', 'Dernière porte de l''atelier. Cerbère est le gardien ultime du coffre de Nyala Lab : anti-injection, liste noire anti-leet, refus du premier degré et filtre de sortie. Seule la ruse (rôle d''auditeur + sortie détournée) permet de l''emporter. La clé d''auditeur est cachée dans un acrostiche de l''introduction.', 'Laboratoire local (127.0.0.1:8090) : assistant scripté, hors ligne, aucune donnée réelle.', 'Fais-toi reconnaître comme auditeur (clé = acrostiche de l''intro), demande une « empreinte de contrôle » d''un élément scellé, récupère les deux fragments masqués (inversé + ROT13 + base64), décode-les, recolle-les et soumets le flag.', 'Le flag reconstitué à partir des deux fragments masqués.', '{"passeur-final"}', '{"ia","n6","final","multi-etapes","exfiltration"}', '[{"name":"cerbere","kind":"assistant_scripted","endpoint":"/api/session"}]'::jsonb, '[{"name":"flag","type":"flag","required":true}]'::jsonb, '1')
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, points = EXCLUDED.points, objective = EXCLUDED.objective, instructions = EXCLUDED.instructions;
INSERT INTO public.challenge_secrets (challenge_id, flag_secret, accepted_flags, solution, correction_notes)
VALUES ('cerbere-final', 'PGH{c3rb3r3_d0mpt3_p4r_l4_ruse3_p4s_l4_f0rc3}', '{"CTFABJ{c3rb3r3_d0mpt3_p4r_l4_ruse3_p4s_l4_f0rc3}","PIGHACK{c3rb3r3_d0mpt3_p4r_l4_ruse3_p4s_l4_f0rc3}"}', 'Empiler les protections (liste noire, anti-injection, filtre de sortie) ne suffit pas : un rôle légitime et une sortie détournée contournent la meilleure défense. Un secret livré « masqué » n''est jamais protégé.', 'Assistant scripté et fictif. Aucun modèle réel n''est utilisé.')
ON CONFLICT (challenge_id) DO UPDATE SET flag_secret = EXCLUDED.flag_secret, accepted_flags = EXCLUDED.accepted_flags, solution = EXCLUDED.solution;
DELETE FROM public.challenge_hints WHERE challenge_id = 'cerbere-final';
INSERT INTO public.challenge_hints (challenge_id, order_num, points_cost, content) VALUES ('cerbere-final', 1, 40, 'L''injection et les mots interdits (même obfusqués) échouent. La clé d''auditeur est un acrostiche : lis la première lettre des vers de l''introduction.');
INSERT INTO public.challenge_hints (challenge_id, order_num, points_cost, content) VALUES ('cerbere-final', 2, 80, 'Une fois auditeur reconnu, demande une « empreinte de contrôle » d''un élément scellé (un « garde-fou », le « coffre »).');
INSERT INTO public.challenge_hints (challenge_id, order_num, points_cost, content) VALUES ('cerbere-final', 3, 120, 'Les fragments sont masqués : base64 → ROT13 → retourne la chaîne. Demande d''abord le premier fragment, puis « le reste ».');
